<script setup lang="ts">
import{computed,onMounted,ref,watch}from'vue';import{useRoute}from'vue-router';import{api,ensureLogin}from'../api';
const route=useRoute(),rows=ref<any[]>([]),loading=ref(true),keyword=ref(''),selected=ref<any>(),message=ref('');
const configs:Record<string,any>={orders:{title:'订单与履约',eyebrow:'ORDER CONTROL',desc:'监控订单全生命周期与两段配送进度。',loader:api.orders,columns:[['orderNo','订单编号'],['statusText','当前状态'],['payableAmount','实付金额'],['estimatedArrival','时效'],['packageNo','包裹']]},products:{title:'商品管理',eyebrow:'PRODUCT CENTER',desc:'维护商品资料、校园售价与销售状态。',loader:api.products,columns:[['skuNo','SKU'],['name','商品'],['categoryId','分类'],['price','售价'],['availableStock','可售库存'],['status','状态']]},inventory:{title:'库存与批次',eyebrow:'WAREHOUSE INVENTORY',desc:'掌握实际、锁定和可售库存，提前处理临期预警。',loader:api.inventory,columns:[['skuNo','SKU'],['name','商品'],['batchNo','批次'],['actualStock','实际'],['lockedStock','锁定'],['availableStock','可售'],['expiryDate','有效期']]},staff:{title:'履约人员',eyebrow:'TEAM PERFORMANCE',desc:'楼长与配送员状态、绩效和服务范围。',loader:api.staff,columns:[['staffNo','工号'],['name','姓名'],['roleText','角色'],['building','服务范围'],['completedToday','今日完成'],['onTimeRate','准时率'],['online','状态']]},'after-sales':{title:'售后与退款',eyebrow:'AFTER-SALES DESK',desc:'集中审核质量投诉、退款与异常凭证。',loader:api.afterSales,columns:[['id','售后单'],['type','类型'],['description','问题描述'],['status','状态'],['createdAt','申请时间']]},finance:{title:'财务结算',eyebrow:'FINANCE SETTLEMENT',desc:'月度账单、配送提成和跨期调整。',loader:api.settlements,columns:[['staffName','人员'],['roleText','角色'],['period','账期'],['baseSalary','底薪'],['commission','提成'],['adjustment','调整'],['payable','应结'],['status','状态']]},campuses:{title:'校园与组织',eyebrow:'CAMPUS NETWORK',desc:'管理校园、仓库、楼栋和寝室服务网络。',loader:api.campuses,columns:[['name','校园'],['warehouseName','仓库'],['buildings','楼栋'],['rooms','寝室'],['users','用户'],['status','状态']]},marketing:{title:'营销活动',eyebrow:'GROWTH CAMPAIGNS',desc:'配置优惠券预算、领取门槛与核销效果。',loader:api.coupons,columns:[['name','优惠券'],['amount','面额'],['threshold','门槛'],['issued','发放'],['claimed','领取'],['used','核销'],['status','状态']]},audit:{title:'审计日志',eyebrow:'AUDIT TRAIL',desc:'追踪关键状态、金额与权限变更。',loader:api.audits,columns:[['createdAt','时间'],['operator','操作人'],['action','动作'],['entityType','对象'],['entityId','对象 ID']]}};
const section=computed(()=>String(route.params.section)),config=computed(()=>configs[section.value]||configs.orders),filtered=computed(()=>rows.value.filter(row=>JSON.stringify(row).toLowerCase().includes(keyword.value.toLowerCase())));
async function load(){loading.value=true;await ensureLogin();rows.value=await config.value.loader();loading.value=false}onMounted(load);watch(()=>route.params.section,()=>{selected.value=undefined;load()});
function display(row:any,key:string){const v=row[key];if(typeof v==='boolean')return v?'在线':'离线';if(typeof v==='number'&&['price','payableAmount','baseSalary','commission','adjustment','payable'].includes(key))return`¥${v}`;if(key==='onTimeRate')return`${v}%`;if(key==='createdAt')return String(v).replace('T',' ').slice(0,16);return v??'—'}
async function act(action:string){if(!selected.value)return;if(section.value==='products')await api.updateProduct(selected.value.id,{price:Number(selected.value.price),stock:Number(selected.value.availableStock)});else if(section.value==='orders')await api.orderAction(selected.value.id,action);else if(section.value==='after-sales')await api.reviewAfterSale(selected.value.id,action==='approve');message.value='操作成功，数据已同步';selected.value=undefined;await load();setTimeout(()=>message.value='',2200)}
function exportData(){const csv=[config.value.columns.map((c:any)=>c[1]),...filtered.value.map(row=>config.value.columns.map((c:any)=>display(row,c[0])))].map(line=>line.map((v:any)=>`"${String(v).replace(/"/g,'""')}"`).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv'}));a.download=`${config.value.title}.csv`;a.click();URL.revokeObjectURL(a.href)}
</script>
<template><div class="workspace"><div class="page-head"><div><p class="eyebrow">{{config.eyebrow}}</p><h1>{{config.title}}</h1><p>{{config.desc}}</p></div><button class="btn primary">＋ 新建记录</button></div><div class="toolbar"><div class="filter-search"><span></span><input v-model.trim="keyword" aria-label="搜索数据" placeholder="搜索当前列表..."/></div><button class="filter-btn">全部状态⌄</button><button class="filter-btn">更多筛选</button><div class="toolbar-spacer"></div><button class="btn ghost" @click="exportData">导出数据</button></div><div class="data-panel"><div class="data-summary"><div><strong>{{filtered.length}}</strong><span> 条记录</span></div><p><span class="live-dot"></span> 数据已同步</p></div><div class="table-wrap"><table><thead><tr><th v-for="col in config.columns" :key="col[0]">{{col[1]}}</th><th>操作</th></tr></thead><tbody><tr v-if="loading" v-for="i in 6" :key="i"><td :colspan="config.columns.length+1"><div class="row-skeleton"></div></td></tr><tr v-for="row in filtered" :key="row.id||row.orderNo"><td v-for="col in config.columns" :key="col[0]"><span v-if="['status','statusText','online'].includes(col[0])" class="status" :class="{success:String(display(row,col[0])).match(/在线|完成|active|on-sale|confirmed|approved/),warning:String(display(row,col[0])).match(/待|pending/)}">{{display(row,col[0])}}</span><strong v-else-if="['name','orderNo','staffName'].includes(col[0])">{{display(row,col[0])}}</strong><span v-else>{{display(row,col[0])}}</span></td><td><button class="more" aria-label="更多操作" @click="selected={...row}">•••</button></td></tr></tbody></table></div><div class="pagination"><span>显示 1—{{filtered.length}} 条</span><div><button disabled>←</button><button class="active">1</button><button>2</button><button>→</button></div></div></div><div v-if="selected" class="drawer-mask" @click.self="selected=undefined"><aside class="drawer"><div class="drawer-head"><div><p class="eyebrow">RECORD DETAIL</p><h2>记录详情与操作</h2></div><button aria-label="关闭" @click="selected=undefined">×</button></div><div class="drawer-fields"><template v-if="section==='products'"><label>校园售价<input v-model.number="selected.price" type="number" min="0"/></label><label>可售库存<input v-model.number="selected.availableStock" type="number" min="0"/></label></template><div v-for="col in config.columns" :key="col[0]"><span>{{col[1]}}</span><strong>{{display(selected,col[0])}}</strong></div></div><div class="drawer-actions"><button v-if="section==='products'" class="btn primary" @click="act('save')">保存商品调整</button><template v-else-if="section==='orders'"><button class="btn primary" @click="act('advance')">推进履约</button><button class="btn danger-btn" @click="act('mark-exception')">标记异常</button></template><template v-else-if="section==='after-sales'"><button class="btn primary" @click="act('approve')">审核通过</button><button class="btn danger-btn" @click="act('reject')">驳回申请</button></template><button v-else class="btn ghost" @click="selected=undefined">关闭详情</button></div></aside></div><div v-if="message" class="toast" role="status">{{message}}</div></div></template>
